INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la durée de conservation des documents relatifs à la relation d''affaires imposée par la réglementation LCB-FT ?', '["3 ans après la fin de la relation d''affaires","5 ans après la fin de la relation d''affaires","10 ans après la fin de la relation d''affaires"]', 1, 'La réglementation impose une conservation de 5 ans après la fin de la relation d''affaires.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''un gel des avoirs ordonné par une résolution du Conseil de sécurité de l''ONU sur les fonds d''une personne désignée ?', '["Les fonds sont bloqués et toute opération est interdite","Les fonds sont confisqués au profit de l''État","Les fonds sont transférés sur un compte séquestre"]', 0, 'Le gel des avoirs interdit toute opération sur les fonds, sans confiscation.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''une déclaration de soupçon sur l''exécution d''une opération ?', '["L''opération doit être exécutée immédiatement","L''opération est interdite définitivement","L''opération peut être différée pendant un délai maximal de 48 heures"]', 2, 'La déclaration de soupçon permet un différé d''exécution de 48 heures maximum.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon le règlement MAR, quelle condition doit remplir une information pour être qualifiée de privilégiée ?', '["Être précise, non publique et susceptible d''influencer notablement le cours.","Être publique mais difficile à interpréter pour les investisseurs.","Être précise et publique, mais avec un impact potentiel sur le cours."]', 0, 'L''information privilégiée doit être précise, non rendue publique et avoir un impact potentiel significatif sur le cours.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est l''obligation d''un émetteur en cas de retard dans la publication d''une information privilégiée ?', '["Il doit publier immédiatement, sans aucune exception.","Il peut reporter la publication sous sa propre responsabilité, sans condition.","Il doit informer l''AMF et peut reporter la publication si ses intérêts légitimes sont en jeu."]', 2, 'L''émetteur peut reporter la publication sous conditions, notamment en informant l''AMF et en préservant ses intérêts légitimes.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une manipulation de marché par diffusion de fausses informations sur le marché ?', '["Elle augmente la liquidité du titre concerné.","Elle fausse le mécanisme de formation des prix.","Elle réduit la volatilité du titre."]', 1, 'La diffusion de fausses informations induit les investisseurs en erreur et fausse les prix.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre annulé avant exécution peut-il constituer une manipulation de marché ?', '["Oui, s''il est utilisé pour donner une fausse indication de l''offre et de la demande.","Non, car aucune transaction n''a eu lieu.","Oui, uniquement s''il est répété plus de dix fois."]', 0, 'L''annulation d''ordres peut être une manipulation si elle vise à tromper le marché sur la liquidité.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle proposition est exacte concernant la notification des opérations des personnes exerçant des responsabilités dirigeantes ?', '["La notification doit être faite à l''AMF dans un délai de 3 jours ouvrés","La notification doit être faite uniquement à l''émetteur dans un délai de 5 jours ouvrés","La notification doit être faite à l''émetteur et à l''AMF dans un délai de 3 jours ouvrés"]', 2, 'Selon MAR, les dirigeants notifient à l''émetteur et à l''AMF dans les 3 jours ouvrés.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle proposition est exacte concernant la manipulation de marché ?', '["La manipulation de marché inclut la diffusion d''informations fausses ou trompeuses","La manipulation de marché ne concerne que les transactions sur actions","La manipulation de marché est uniquement sanctionnée si elle entraîne un profit"]', 0, 'La manipulation de marché comprend notamment la diffusion d''informations fausses ou trompeuses.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un investisseur détient une information privilégiée. Quelle proposition est exacte ?', '["Il peut négocier s''il attend 24 heures après la publication","Il lui est interdit de négocier tant que l''information n''est pas publiée","Il peut négocier si l''information est déjà publique dans un autre pays"]', 1, 'L''interdiction de négociation sur information privilégiée s''applique jusqu''à sa publication.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon le règlement MAR, quelle est l''obligation d''un émetteur concernant une information privilégiée ?', '["La publier dès que possible, sauf report autorisé","La transmettre uniquement à l''AMF","La garder confidentielle pendant 30 jours"]', 0, 'L''émetteur doit publier sans délai l''information privilégiée, mais peut reporter la publication sous conditions.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la durée de la période de négociation pour les dirigeants avant la publication des résultats annuels selon le règlement MAR ?', '["15 jours ouvrés","60 jours calendaires","30 jours calendaires"]', 2, 'La période de négociation est de 30 jours calendaires avant la publication du rapport annuel.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre du conseil en investissement, quelle obligation incombe au conseiller vis-à-vis du client ?', '["Évaluer l''expérience et les connaissances du client uniquement si celui-ci le demande","Évaluer l''expérience et les connaissances du client et fournir un rapport de pertinence","Évaluer l''expérience et les connaissances du client uniquement pour les produits complexes"]', 1, 'Le conseiller doit évaluer les connaissances et l''expérience du client et fournir un rapport de pertinence avant de recommander un investissement.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon MIFID II, quelles sont les conditions pour qu''un incitatif (commission) soit autorisé dans la commercialisation ?', '["Les incitatifs sont toujours interdits, quel que soit le contexte","Les incitatifs sont autorisés s''ils sont de faible valeur et non monétaires","Les incitatifs sont autorisés s''ils améliorent la qualité du service et sont divulgués au client"]', 2, 'Les incitatifs sont permis s''ils améliorent la qualité du service et sont clairement divulgués, conformément à MIFID II.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle caractéristique définit un ordre à cours limité ?', '["Il garantit l''exécution au prix limite ou à un prix meilleur, mais pas l''exécution elle-même","Il garantit l''exécution immédiate au prix du marché","Il garantit à la fois l''exécution et le prix limite"]', 0, 'Un ordre à cours limité fixe un prix maximal (achat) ou minimal (vente) mais ne garantit pas que l''ordre sera exécuté.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'En matière d''exécution des ordres, que signifie l''obligation de ''meilleure exécution'' pour une entreprise d''investissement ?', '["Obtenir systématiquement le prix le plus bas du marché","Prendre toutes les mesures suffisantes pour obtenir le meilleur résultat possible en considérant prix, coûts, rapidité et autres facteurs","Exécuter l''ordre au prix moyen du marché à un instant donné"]', 1, 'La meilleure exécution exige de considérer plusieurs facteurs (prix, coûts, vitesse, probabilité d''exécution) pour obtenir le meilleur résultat pour le client.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon MIFID II, quelle est l''obligation d''une entreprise d''investissement lorsqu''elle fournit un service de conseil en investissement ?', '["Évaluer l''adéquation (suitability) et fournir un rapport sur l''adéquation","Évaluer uniquement la connaissance et l''expérience du client (appropriateness)","Vérifier que le client dispose de moyens financiers suffisants"]', 0, 'Le conseil en investissement exige un test d''adéquation et un rapport écrit.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans la commercialisation de produits financiers, quelle est la règle sur les incitations (rétrocessions) versées par un tiers ?', '["Elles sont interdites sauf si elles améliorent la qualité du service et sont divulguées","Elles sont autorisées sans condition si elles figurent au contrat","Elles sont autorisées uniquement si elles proviennent de l''émetteur du produit"]', 0, 'Les incitations ne sont permises que si elles améliorent la qualité du service et sont transparentes.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un client passe un ordre à cours limité pour acheter une action à 50 € alors que le cours est de 52 €. Que se passe-t-il ?', '["L''ordre est exécuté immédiatement à 50 €","L''ordre est enregistré et exécuté si le cours atteint 50 € ou moins","L''ordre est rejeté car le prix est inférieur au cours du marché"]', 1, 'Un ordre à cours limité n''est exécuté que si le marché atteint le prix limite ou mieux.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre de la commercialisation d''un instrument financier complexe à un client non professionnel, quelle est l''obligation de l''entreprise d''investissement ?', '["Réaliser un test d''adéquation (suitability) systématique avant toute transaction.","Réaliser un test de caractère approprié (appropriateness) avant la transaction.","S''abstenir de toute transaction si le client refuse de fournir des informations."]', 1, 'Pour les instruments complexes, un test d''appropriateness est requis, contrairement au suitability qui s''applique au conseil ou à la gestion de portefeuille.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de commercialisation d''instruments financiers, quelle proposition relative aux incitations (inducements) est exacte ?', '["Les incitations sont interdites en toutes circonstances.","Les incitations sont autorisées si elles améliorent la qualité du service et sont divulguées au client.","Les incitations sont autorisées si elles sont inférieures à 100 euros."]', 2, 'Les incitations sont permises si elles visent à améliorer la qualité du service et sont clairement divulguées, sans seuil monétaire fixe.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre à cours limité est un ordre qui :', '["Garantit l''exécution au prix limite ou mieux.","Ne peut être exécuté que si le prix du marché atteint le prix limite.","Est exécuté au prix du marché dès réception."]', 0, 'L''ordre à cours limité n''est exécuté que si le marché atteint le prix limite ou un prix plus favorable, sans garantie d''exécution.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la réglementation, quelle obligation s''impose à un prestataire de services d''investissement lors de la recommandation d''un instrument financier à un client non professionnel ?', '["Évaluer l''adéquation (suitability)","Évaluer le caractère approprié (appropriateness)","Fournir une information neutre sur les risques"]', 0, 'Pour un conseil personnalisé, l''adéquation est obligatoire, contrairement à l''appropriateness pour les services sans conseil.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre de la relation client, qu''est-ce que le devoir de conseil impose au conseiller en investissements financiers ?', '["Proposer systématiquement les produits les plus rentables","Adapter ses recommandations au profil et aux objectifs du client","Garantir la performance des placements"]', 1, 'Le devoir de conseil exige une adaptation au profil du client, sans garantie de performance.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre à cours limité est exécuté uniquement si le prix du marché atteint ou dépasse le prix limite. Quelle affirmation est exacte ?', '["Il garantit l''exécution au prix limite","Il peut ne pas être exécuté si le prix limite n''est pas atteint","Il est exécuté au meilleur prix disponible immédiatement"]', 1, 'L''ordre à cours limité n''est exécuté que si le marché atteint le prix limite, sinon il reste en attente.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Pour un ordre de grande taille, quel facteur prédomine dans la politique de meilleure exécution ?', '["La rapidité d''exécution","La probabilité d''exécution","Le coût total de la transaction"]', 2, 'Pour les ordres importants, le coût total (frais, prix, impact) est le critère déterminant.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre de la directive MIF 2, quelle obligation s''impose à un prestataire de services d''investissement lors de la fourniture d''un service de conseil en investissement ?', '["Obtenir l''accord écrit du client pour chaque transaction","Évaluer l''adéquation du service au profil du client","Fournir une information claire sur les coûts et charges"]', 1, 'Le conseil en investissement exige une évaluation de l''adéquation (suitability) pour recommander des instruments adaptés.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la durée minimale de conservation des enregistrements des communications téléphoniques et électroniques entre un prestataire et ses clients, conformément à la réglementation MIF 2 ?', '["5 ans","3 ans","10 ans"]', 0, 'MIF 2 impose une conservation d''au moins 5 ans pour ces enregistrements.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un client passe un ordre d''achat de 100 actions à cours limité à 50 euros, alors que le cours est à 52 euros. Que se passe-t-il ?', '["L''ordre est exécuté immédiatement au cours de 52 euros","L''ordre est rejeté car le cours est supérieur à la limite","L''ordre est enregistré et sera exécuté si le cours atteint 50 euros ou moins"]', 2, 'Un ordre à cours limité n''est exécuté qu''au prix limite ou meilleur, donc il attend une baisse du cours.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la réglementation MIFID, quelle est l''obligation d''une entreprise d''investissement en matière de conflits d''intérêts ?', '["Elle doit toujours éviter tout conflit d''intérêts, sans exception.","Elle doit identifier, prévenir ou gérer les conflits d''intérêts et informer le client si les mesures ne suffisent pas.","Elle doit informer le client uniquement après la transaction."]', 1, 'L''entreprise doit gérer les conflits et informer le client si nécessaire, mais ne peut pas les éviter totalement.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre à cours limité d''achat à 100 € est passé alors que le cours est de 105 €. Que se passe-t-il ?', '["L''ordre reste en attente jusqu''à ce que le cours atteigne 100 € ou moins.","L''ordre est exécuté immédiatement au cours de 100 €.","L''ordre est annulé automatiquement."]', 0, 'Un ordre à cours limité n''est exécuté que si le cours atteint le prix limite ou mieux.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la particularité d''un ordre à seuil de déclenchement (stop) ?', '["Il garantit l''exécution au prix du seuil.","Il est exécuté uniquement si le cours revient au seuil après l''avoir dépassé.","Il se transforme en ordre au marché une fois le seuil atteint."]', 2, 'Un ordre stop devient un ordre au marché dès que le seuil est touché, sans garantie de prix.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale différence entre un jeton utilitaire et un jeton de sécurité ?', '["Le jeton utilitaire confère des droits de propriété sur l''entreprise.","Le jeton de sécurité est soumis à la réglementation financière.","Le jeton utilitaire est toujours émis par une banque centrale."]', 1, 'Le jeton de sécurité représente un investissement et relève de la réglementation financière.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''impact d''une augmentation de la volatilité sur la valeur d''une option ?', '["La valeur de l''option augmente.","La valeur de l''option diminue.","La valeur de l''option reste inchangée."]', 0, 'Une volatilité accrue augmente la probabilité de mouvement du sous-jacent, donc la prime de l''option.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre de la tokenisation d''un actif immobilier, que représente le jeton ?', '["Un droit de vote uniquement.","Une garantie de rendement fixe.","Une part de propriété de l''actif."]', 2, 'Le jeton représente une fraction de propriété de l''actif immobilier.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale caractéristique d''un stablecoin adossé à une monnaie fiduciaire ?', '["Sa valeur est garantie par un algorithme.","Il est indexé sur la valeur d''une monnaie légale.","Il est émis par une banque centrale."]', 1, 'Le stablecoin est adossé à une réserve de monnaie légale pour maintenir sa parité.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Selon le règlement MiCA, un crypto-actif qui vise à maintenir une valeur stable en se référant à une seule monnaie officielle est qualifié de :', '["token de monnaie électronique","token adossé à des actifs","token utilitaire"]', 0, 'Le règlement MiCA définit le token de monnaie électronique comme un crypto-actif adossé à une seule monnaie officielle.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la fonction principale d''un token utilitaire (utility token) ?', '["Conférer des droits de vote dans la gouvernance de l''émetteur","Donner accès à un service ou à une fonctionnalité numérique","Représenter une créance sur l''émetteur"]', 1, 'Un token utilitaire donne accès à un bien ou un service numérique, sans conférer de droits financiers.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''un hard fork sur une blockchain ?', '["La chaîne est temporairement interrompue puis reprend avec un nouveau protocole","Tous les détenteurs de crypto-actifs perdent leurs avoirs","La chaîne se divise en deux chaînes distinctes avec un historique commun jusqu''au fork"]', 2, 'Un hard fork crée une divergence permanente de la blockchain, aboutissant à deux chaînes indépendantes.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale différence entre un security token et un utility token ?', '["Le security token confère des droits financiers, le utility token donne accès à un service","Le security token est émis sur une blockchain privée, le utility token sur une publique","Le utility token est toujours régulé par l''AMF, le security token ne l''est jamais"]', 0, 'Un security token représente un investissement (droits financiers), un utility token donne droit à un usage.', 7, 'Instruments financiers et crypto-actifs');
